begin;
create table if not exists public.external_institutions(id uuid primary key,provider text not null,provider_institution_id text not null,name text not null,display_name text,brand_name text,logo_url text,country text not null default 'BR',institution_type text,supported_products jsonb not null default '[]',supported_account_types jsonb not null default '[]',status text not null default 'unknown',provider_schema_version text,metadata jsonb not null default '{}',last_seen_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider,provider_institution_id));
create table if not exists public.financial_connections(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,provider text not null,provider_connection_id text,external_source_id uuid,institution_id uuid,consent_id uuid,status text not null check(status in('created','connecting','awaiting_consent','active','requires_reauthentication','expired','revoked','failed','disconnected')),environment text not null check(environment in('mock','sandbox','production')),provider_schema_version text,last_successful_sync_at timestamptz,last_attempt_at timestamptz,next_action text,failure_code text,failure_message_redacted text,credential_reference text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),revoked_at timestamptz,deleted_at timestamptz,unique(user_id,id),unique(user_id,provider,provider_connection_id),foreign key(user_id,external_source_id) references public.external_sources(user_id,id),foreign key(institution_id) references public.external_institutions(id));
create table if not exists public.open_finance_consents(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,financial_connection_id uuid not null,provider text not null,provider_consent_id text not null,status text not null check(status in('pending','awaiting_user','authorized','active','expired','revoked','rejected','failed','requires_action','unknown')),scopes jsonb not null default '[]',authorized_at timestamptz,expires_at timestamptz,renewal_required_at timestamptz,revoked_at timestamptz,rejection_reason text,failure_code text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,id),unique(user_id,provider,provider_consent_id),foreign key(user_id,financial_connection_id) references public.financial_connections(user_id,id));
alter table public.financial_connections drop constraint if exists financial_connections_consent_fkey;alter table public.financial_connections add constraint financial_connections_consent_fkey foreign key(user_id,consent_id) references public.open_finance_consents(user_id,id) deferrable initially deferred;
alter table public.external_accounts add column if not exists financial_connection_id uuid,add column if not exists provider_account_id text,add column if not exists provider_schema_version text,add column if not exists quality text not null default 'complete',add column if not exists reappeared_at timestamptz;
alter table public.external_accounts drop constraint if exists external_accounts_connection_fkey;alter table public.external_accounts add constraint external_accounts_connection_fkey foreign key(user_id,financial_connection_id) references public.financial_connections(user_id,id);
create unique index if not exists external_accounts_provider_account_uidx on public.external_accounts(user_id,financial_connection_id,provider_account_id) where provider_account_id is not null;
create table if not exists public.open_finance_sync_cursors(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,financial_connection_id uuid not null,resource_type text not null,cursor text,window_start timestamptz,window_end timestamptz,provider_checkpoint text,last_successful_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,id),unique(user_id,financial_connection_id,resource_type),foreign key(user_id,financial_connection_id) references public.financial_connections(user_id,id));
create table if not exists public.connection_events(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,financial_connection_id uuid,consent_id uuid,provider text not null,event_type text not null,provider_event_id text,correlation_id uuid,idempotency_key text not null,status text not null,payload_summary jsonb not null default '{}',error_code text,error_message_redacted text,occurred_at timestamptz,received_at timestamptz not null default now(),processed_at timestamptz,created_at timestamptz not null default now(),unique(user_id,id),unique(user_id,idempotency_key),foreign key(user_id,financial_connection_id) references public.financial_connections(user_id,id),foreign key(user_id,consent_id) references public.open_finance_consents(user_id,id));
create table if not exists public.open_finance_callback_states(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,financial_connection_id uuid not null,provider text not null,state_hash text not null,correlation_id uuid not null,expires_at timestamptz not null,used_at timestamptz,created_at timestamptz not null default now(),unique(user_id,id),unique(state_hash),foreign key(user_id,financial_connection_id) references public.financial_connections(user_id,id));
create index if not exists financial_connections_status_idx on public.financial_connections(user_id,status,updated_at desc) where deleted_at is null;create index if not exists consents_expiry_idx on public.open_finance_consents(user_id,status,expires_at);create index if not exists connection_events_connection_idx on public.connection_events(user_id,financial_connection_id,received_at desc);create index if not exists callback_states_expiry_idx on public.open_finance_callback_states(expires_at) where used_at is null;
insert into public.schema_versions(component,version,migration_name,checksum,metadata) values('open-finance-gateway',1,'012_create_open_finance_gateway_schema','phase6-v1','{"phase":6,"officialSync":false,"credentials":"opaque_reference_only"}'::jsonb) on conflict(component) do update set version=excluded.version,applied_at=now(),migration_name=excluded.migration_name,checksum=excluded.checksum,metadata=excluded.metadata;
commit;
